import com.webcommander.client.ApiResponse;
import java.util.List;
import java.util.Map;

ApiResponse response = client.trash().listTrash(
        Map.of("type", "Category", "search", "spring", "sort", "name", "order", "asc", "limit", 20));
Map<?, ?> body = (Map<?, ?>) response.getMap();
for (Object row : (List<?>) body.get("items")) {
    Map<?, ?> item = (Map<?, ?>) row;
    System.out.println(item.get("id") + " " + item.get("type") + " " + item.get("name") + " " + item.get("removed_at"));
}
System.out.println(((Map<?, ?>) body.get("pagination")).get("total"));

