bulk_restore_trash.code:
import com.webcommander.client.ApiResponse;
import java.util.List;
import java.util.Map;

ApiResponse response = client.trash().bulkRestoreTrash(Map.of("items", List.of(
        Map.of("type", "Category", "id", 1234), Map.of("type", "BlogPost", "id", 99))));
Map<?, ?> body = (Map<?, ?>) response.getMap();
System.out.println(((List<?>) body.get("restored")).size());
for (Object row : (List<?>) body.get("failed")) {
    Map<?, ?> failure = (Map<?, ?>) row;
    System.out.println(failure.get("type") + " " + failure.get("id") + " " + failure.get("code") + " " + failure.get("message"));
}

